mmary">折叠标题</label><input id="dialog-summary" v-model="dialogForm.summary" maxlength="120" required /><label for="dialog-body">折叠内容</label><textarea id="dialog-body" v-model="dialogForm.body" rows="4" required></textarea></div><div v-if="dialog.kind === 'callout'" class="field"><label for="dialog-tone">提示卡类型</label><select id="dialog-tone" v-model="dialogForm.tone"><option value="info">信息</option><option value="note">笔记</option><option value="warning">注意</option><option value="success">完成</option></select></div><div v-if="dialog.kind === 'mathInline' || dialog.kind === 'mathBlock'" class="field"><label for="dialog-math">LaTeX（禁止 HTML、宏和外部命令）</label><textarea id="dialog-math" v-model="dialogForm.value" rows="4" required placeholder="\\frac{a}{b}"></textarea></div><div v-if="dialog.kind === 'mermaid'" class="field"><label for="dialog-mermaid">安全 Mermaid diagram</label><textarea id="dialog-mermaid" v-model="dialogForm.value" rows="7" required placeholder="flowchart TD&#10;  A[开始] --> B[结束]"></textarea></div><div v-if="dialog.kind === 'footnote'" class="field"><label for="dialog-footnote-label">脚注标识</label><input id="dialog-footnote-label" v-model="dialogForm.label" maxlength="30" required /><label for="dialog-footnote-text">脚注内容</label><textarea id="dialog-footnote-text" v-model="dialogForm.text" rows="3" required></textarea></div><div v-if="dialog.kind === 'code'" class="field"><label for="dialog-language">代码语言</label><select id="dialog-language" v-model="dialogForm.language"><option v-for="language in languages" :key="language" :value="language">{{ language }}</option></select></div><div v-if="dialog.kind === 'media'" class="field"><label for="dialog-label">媒体/附件名称</label><input id="dialog-label" v-model="dialogForm.label" required maxlength="255" /></div><p v-if="dialogError" class="error" role="alert">{{ dialogError }}</p><div class="dialog-actions"><button class="button button-secondary" type="button" @click="closeDialog">取消</button><button class="button button-pr