function makeEditor(content:any = null){ editor.value?.destroy(); editor.value = new Editor({ extensions:createExtensions(), content:content || { type:'doc', content:[{ type:'paragraph' }] }, editorProps:{ handleKeyDown:(_view,event) => { if (event.key === '/' && editor.value?.state.selection.$from.parent.type.name === 'paragraph' && editor.value.state.selection.$from.parent.content.size === 0) { slashOpen.value = true; return true } if (event.key === 'Escape' && slashOpen.value) { slashOpen.value = false; return true } return false } }, onUpdate:() => markDirty() }); }
function run(action:() => boolean|undefined){ action(); markDirty() }
function toggleHeading(level:number){ run(() => editor.value?.chain().focus().toggleHeading({ level:level as 1|2|3|4 }).run()) }
function insertTable(){ run(() => editor.value?.chain().focus().insertTable({ rows:3, cols:3, withHeaderRow:true }).run()) }
function insertSlashItem(action:string){ slashOpen.value = false; if (action === 'heading') toggleHeading(2); else if (action === 'quote') run(() => editor.value?.chain().focus().toggleBlockquote().run()); else if (action === 'list') run(() => editor.value?.chain().focus().toggleBulletList().run()); else if (action === 'code') openDialog('code'); else if (action === 'callout') openDialog('callout'); else if (action === 'details') openDialog('details'); else if (action === 'bookmark') openDialog('bookmark'); else run(() => editor.value?.chain().focus().setHorizontalRule().run()) }
function currentContent(){ return mode.value === 'blocks' ? editor.value?.getText({ blockSeparator:'\n' }) || '' : form.value.contentMarkdown }
function hasMeaningfulContent(){ return hasMeaningfulDraftContent({ title:form.value.title, excerpt:form.value.excerpt, content:currentContent() }) }
function recoveryIdentity(){ try { const cached = JSON.parse(localStorage.getItem('userInfo') || '{}'); return String(cached.id || cached.email || 'current') } catch (_) { return 'current' } }
function recoveryKey(id: number|null = postId.value){ return `own-web-editor-recovery:${recoveryIdentity()}:${id || 'new'}` }
function persistRecovery(){ if (!dirty.value || (!postId.value && !hasMeaningfulContent())) return; try { const snapshot = { savedAt:Date.now(), mode:mode.value, form:form.value, blocks:mode.value === 'blocks' ? editor.value?.getJSON() : null }; const serialized = JSON.stringify(snapshot); if (serialized.length <= 900_000) localStorage.setItem(recoveryKey(), serialized) } catch (_) {} }
function clearRecovery(){ try { localStorage.removeItem(recoveryKey()); localStorage.removeItem(recoveryKey(null)) } catch (_) {} }
async function restoreRecovery(){
  let snapshot:any = null
  try { const raw = localStorage.getItem(recoveryKey()); if (raw) snapshot = JSON.parse(raw) } catch (_) { snapshot = null }
  if (!snapshot || !snapshot.savedAt || Date.now() - Number(snapshot.savedAt) > 7 * 24 * 60 * 60 * 1000) { if (snapshot) clearRecovery(); return }
  if (!await askConfirmation('恢复未保存内容', '发现本地保留的未保存内容。是否恢复到编辑器？')) { clearRecovery(); return }
  if (snapshot.form && typeof snapshot.form === 'object') form.value = { ...form.value, ...snapshot.form }
