function localPreview(){ if (mode.value === 'blocks' && editor.value) return sanitize(editor.value.getHTML()); return `<p>${escapeText(form.value.contentMarkdown)}</p>` }
async function refreshPreview(){ if (loading.value) return; try { const response = await http.post('/api/editor/preview', { postId:postId.value, contentFormat:mode.value, ...(mode.value === 'blocks' ? { contentBlocks:editor.value?.getJSON() } : { contentMarkdown:form.value.contentMarkdown }) }); previewHtml.value = sanitize(response.data.html || '') } catch (_) { previewHtml.value = localPreview() } }
function queuePreview(){ if (previewTimer.value) window.clearTimeout(previewTimer.value); previewTimer.value = window.setTimeout(() => { void refreshPreview() }, 250) }
function markDirty(){ if (loading.value) return; dirty.value = true; saveState.value = 'unsaved'; persistRecovery(); queueAutosave(); queuePreview() }
function askConfirmation(title:string, message:string, options:{ confirmLabel?:string; danger?:boolean } = {}){ confirmDialog.value = { open:true, title, message, confirmLabel:options.confirmLabel || '继续', danger:Boolean(options.danger) }; const promise = new Promise<boolean>((resolve) => { confirmResolver = resolve }); nextTick(() => confirmButton.value?.focus()); return promise }
function resolveConfirmation(result:boolean){ const resolver = confirmResolver; confirmResolver = null; confirmDialog.value.open = false; resolver?.(result) }
function resetDialog(kind:DialogKind){ dialogForm.value = { url:'', title:'', description:'', summary:'展开阅读', body:'', tone:'info', value:'', label:selectedFile.value?.name || '', text:'', language:'text', alt:selectedFile.value?.name || '', caption:'', width:100, align:'center' }; dialog.value = { open:true, kind }; dialogError.value = '' }
function openDialog(kind:DialogKind){ resetDialog(kind) }
function closeDialog(){ if (!dialogBusy.value) { dialog.value.open = false; dialogError.value = '' } }
async function switchMode(next:Mode){ if (next === mode.value) return; const hasContent = Boolean(currentContent().trim()); if (hasContent && !await askConfirmation('切换内容模式', '切换内容模式会生成派生格式并保留当前原始格式，确定继续吗？')) return; if (next === 'markdown') form.value.contentMarkdown = (editor.value as any)?.getMarkdown?.() || editor.value?.getText({ blockSeparator:'\n' }) || ''; else { makeEditor(); try { (editor.value?.commands as any).setContent(form.value.contentMarkdown || '', { contentType:'markdown' }) } catch (_) {} } mode.value = next; markDirty() }
function scheduleValue(){ return form.value.scheduledAt ? `${form.value.scheduledAt}:00${form.value.timezone}` : null }
function payload(status?:string){ const data:any = { title:form.value.title, excerpt:form.value.excerpt, slug:form.value.slug, visibility:form.value.visibility, allowComments:form.value.allowComments, categorySlugs:form.value.categorySlugs, tags:form.value.tagText.split(',').map((item) => item.trim()).filter(Boolean), contentFormat:mode.value, coverImage:form.value.coverImage, coverAltText:form.value.coverAltText, contentSource:'editor' }; if (mode.value === 'blocks') data.contentBlocks = editor.value?.getJSON(); else data.contentMarkdown = form.value.contentMarkdown; if (status) { data.status = status; data.scheduledAt = status === 'scheduled' ? scheduleValue() : null } return data }
async function ensureDraft(options:{ allowEmpty?:boolean } = {}){ if (postId.value) return; if (!options.allowEmpty && !hasMeaningfulContent()) throw new Error('请先填写标题或正文'); const response = await http.post('/api/posts', { title:form.value.title || '未命名草稿', contentFormat:mode.value, ...(mode.value === 'blocks' ? { contentBlocks:editor.value?.getJSON() } : { contentMarkdown:form.value.contentMarkdown }) }); postId.value = response.data.post.id; postStatus.value = 'draft' }
async function replaceAfterPersistence(){ if (!postId.value || route.params.id) return; allowInternalNavigation.value = true; try { await router.replace(`/posts/${postId.value}/edit`) } finally { allowInternalNavigation.value = false } }
function queueAutosave(){ if (timer.value) window.clearTimeout(timer.value); timer.value = window.setTimeout(async() => { if (!dirty.value || saving.value || (!postId.value && !hasMeaningfulContent())) return; saving.value = true; saveState.value = 'saving'; try { const wasNew = !postId.value; await ensureDraft(); const response = await http.post(`/api/posts/${postId.value}/autosave`, payload()); lastSaved.value = new Date(response.data.savedAt).toLocaleTimeString('zh-CN', { hour:'2-digit', minute:'2-digit' }); dirty.value = false; saveState.value = 'saved'; clearRecovery(); if (wasNew) await replaceAfterPersistence() } catch (e:any) { persistRecovery(); error.value = e.response?.data?.error?.message || '自动保存失败'; saveState.value = 'failed' } finally { saving.value = false } }, 1200) }
async function save(status:'draft'|'scheduled'|'published'){ if (!hasMeaningfulContent()) { error.value = '请先填写标题或正文'; return } if (status === 'scheduled' && !scheduleValue()) { error.value = '安排发布前请填写带时区的未来时间'; return } saving.value = true; saveState.value = 'saving'; error.value = ''; try { const wasNew = !postId.value; await ensureDraft(); const response = await http.put(`/api/posts/${postId.value}`, payload(status)); postStatus.value = status; if (status === 'draft') form.value.scheduledAt = ''; if (status === 'published') { allowInternalNavigation.value = true; try { await router.push('/creation') } finally { allowInternalNavigation.value = false } } else { if (wasNew) await replaceAfterPersistence(); if (response.data?.status === 'scheduled') form.value.scheduledAt = String(response.data.scheduledAt).slice(0,16) } lastSaved.value = '刚刚'; dirty.value = false; saveState.value = 'saved'; clearRecovery() } catch (e:any) { persistRecovery(); error.value = e.response?.data?.error?.message || '保存失败，请稍后重试'; saveState.value = 'failed' } finally { saving.value = false } }
async function deleteDraft(){ if (!postId.value || postStatus.value === 'published') return; if (!await askConfirmation('删除草稿', '此操作会删除文章及其修订，且无法从创作中心恢复。确定删除吗？', { confirmLabel:'删除草稿', danger:true })) return; saving.value = true; error.value = ''; try { await http.delete(`/api/posts/${postId.value}`); clearRecovery(); allowInternalNavigation.value = true; try { await router.push('/creation') } finally { allowInternalNavigation.value = false } } catch (e:any) { error.value = e.response?.data?.error?.message || '删除草稿失败' } finally { saving.value = false } }
async function submitDialog(){ dialogBusy.value = true; dialogError.value = ''; try { const kind = dialog.value.kind; if (kind === 'link') { if (!/^https?:\/\//i.test(dialogForm.value.url)) throw new Error('链接仅支持 HTTP 或 HTTPS'); editor.value?.chain().focus().extendMarkRange('link').setLink({ href:dialogForm.value.url.trim() }).run() } else if (kind === 'embed') insertSafeEmbed(dialogForm.value.url); else if (kind === 'bookmark') insertSafeBookmark(dialogForm.value.url, dialogForm.value.title, dialogForm.value.description); else if (kind === 'callout') editor.value?.chain().focus().insertContent({ type:'callout', attrs:{ tone:dialogForm.value.tone }, content:[{ type:'text', text:'在这里写提示内容' }] }).run(); else if (kind === 'details') editor.value?.chain().focus().insertContent({ type:'details', attrs:{ summary:dialogForm.value.summary.trim(), body:dialogForm.value.body } }).run(); else if (kind === 'mathInline' || kind === 'mathBlock') editor.value?.chain().focus().insertContent({ type:kind, attrs:{ value:dialogForm.value.value.trim() } }).run(); else if (kind === 'mermaid') editor.value?.chain().focus().insertContent({ type:'mermaid', attrs:{ value:dialogForm.value.value.trim() } }).run(); else if (kind === 'footnote') editor.value?.chain().focus().insertContent({ type:'footnote', attrs:{ label:dialogForm.value.label, text:dialogForm.value.text } }).run(); else if (kind === 'code') editor.value?.chain().focus().toggleCodeBlock().updateAttributes('codeBlock', { language:dialogForm.value.language }).run(); else if (['image','gallery','cover','media'].includes(kind)) await uploadSelected(kind); if (!['image','gallery','cover','media'].includes(kind)) markDirty(); closeDialog() } catch (e:any) { dialogError.value = e.message || e.response?.data?.error?.message || '操作未完成' } finally { dialogBusy.value = false } }
function insertSafeEmbed(value:string){ const parsed = new URL(value.trim()); if (parsed.protocol !== 'https:' || !['www.youtube.com','youtu.be','www.bilibili.com','open.spotify.com'].includes(parsed.hostname)) throw new Error('仅支持允许列表中的 HTTPS 嵌入链接'); editor.value?.chain().focus().insertContent({ type:'embed', attrs:{ provider:parsed.hostname, url:parsed.toString() } }).run() }
function insertSafeBookmark(value:string,title:string,description:string){ const parsed = new URL(value.trim()); if (parsed.protocol !== 'https:' || !['www.youtube.com','youtu.be','www.bilibili.com','open.spotify.com'].includes(parsed.hostname)) throw new Error('Bookmark Card 仅支持允许列表中的 HTTPS 链接'); editor.value?.chain().focus().insertContent({ type:'bookmarkCard', attrs:{ provider:parsed.hostname, url:parsed.toString(), title:title.trim(), description:description.trim() } }).run() }
function selectImage(event:Event){ selectedFile.value = (event.target as HTMLInputElement).files?.[0] || null; if (selectedFile.value) resetDialog('image'); (event.target as HTMLInputElement).value = '' }
function selectGallery(event:Event){ selectedFiles.value = [...((event.target as HTMLInputElement).files || [])].slice(0,20); if (selectedFiles.value.length) { resetDialog('gallery'); dialogForm.value.alt = selectedFiles.value.map((file) => file.name.replace(/\.[^.]+$/, '')).join('\n') } (event.target as HTMLInputElement).value = '' }
