async function uploadSelected(kind:DialogKind){ if (kind === 'gallery') { const alts = String(dialogForm.value.alt).split('\n').map((item) => item.trim()).filter(Boolean); if (alts.length !== selectedFiles.value.length) throw new Error('图库中每张图片都必须有一行替代文本'); const items = []; for (let index = 0; index < selectedFiles.value.length; index += 1) { const galleryFile = selectedFiles.value[index]; const alt = alts[index]; if (!galleryFile || !alt) throw new Error('图库文件或替代文本无效'); items.push(await uploadOne(galleryFile, 'image', alt, '')) } if (mode.value === 'blocks') editor.value?.chain().focus().insertContent({ type:'gallery', attrs:{ items:items.map((item:any) => ({ src:item.url, alt:item.altText })) } }).run(); else form.value.contentMarkdown += `\n\n${items.map((item:any) => `![${item.altText}](${item.url})`).join('\n\n')}\n`; selectedFiles.value = []; await loadMedia(); markDirty(); return } const file = selectedFile.value; if (!file) throw new Error('请选择文件'); if (kind === 'cover') { const media = await uploadOne(file, 'image', dialogForm.value.alt.trim(), ''); form.value.coverImage = media.url; form.value.coverAltText = dialogForm.value.alt.trim(); selectedFile.value = null; await loadMedia(); markDirty(); return } if (kind === 'media') { const media = await uploadOne(file, 'media', '', dialogForm.value.label.trim()); if (mode.value === 'blocks') editor.value?.chain().focus().insertContent({ type:media.kind === 'file' ? 'attachment' : media.kind, attrs:{ src:media.url, label:media.label } }).run(); else form.value.contentMarkdown += `\n\n[${media.label}](${media.url})\n`; selectedFile.value = null; await loadMedia(); markDirty(); return } const media = await uploadOne(file, 'image', dialogForm.value.alt.trim(), ''); if (mode.value === 'blocks') editor.value?.chain().focus().insertContent({ type:'image', attrs:{ src:media.url, alt:media.altText, caption:dialogForm.value.caption, width:dialogForm.value.width, align:dialogForm.value.align } }).run(); else form.value.contentMarkdown += `\n\n![${media.altText}](${media.url})\n`; selectedFile.value = null; await loadMedia(); markDirty() }
