function formatDate(value:string){ return new Intl.DateTimeFormat('zh-CN', { dateStyle:'medium', timeStyle:'short' }).format(new Date(value)) }
async function loadPost(){ if (!postId.value) return; const post = (await http.get(`/api/posts/${postId.value}`)).data.post; postStatus.value = post.status || 'draft'; form.value = { title:post.title || '', excerpt:post.excerpt || '', contentMarkdown:post.content_markdown || '', slug:post.slug || '', visibility:post.visibility || 'private', allowComments:Boolean(post.allow_comments), scheduledAt:post.scheduled_at ? String(post.scheduled_at).slice(0,16) : '', timezone:'+08:00', categorySlugs:post.categorySlugs || [], tagText:(post.tags || []).join(', '), coverImage:post.cover_image || null, coverAltText:post.cover_alt_text || '' }; mode.value = post.content_format === 'blocks' ? 'blocks' : 'markdown'; makeEditor(mode.value === 'blocks' && post.content_blocks ? (typeof post.content_blocks === 'string' ? JSON.parse(post.content_blocks) : post.content_blocks) : null); await Promise.all([loadRevisions(), loadMedia()]) }
